/* v74: thẻ hộ trong Xác nhận thu tiền – cùng kiểu thẻ Khách báo nộp tiền (anh Phong 08/11 04:11) */
.ds-tt { grid-template-columns:repeat(auto-fill, minmax(360px,1fr)); gap:12px; }
@media (max-width:600px) { .ds-tt { grid-template-columns:1fr; } }
.tt-ho { display:flex; flex-direction:column; gap:8px; border:1px solid var(--vien); border-left:6px solid #ef5350; border-radius:14px; padding:12px 14px; background:#fff; box-shadow:var(--bong); transition:background .3s, border-color .3s; }
.tt-ho .nt-tien { color:var(--do); } .tt-ho.da .nt-tien { color:var(--la); }
.tt-ho .nt-nut.chua.on { background:#fdecea; border-color:#ef5350; color:#c62828; }
.tt-ho .tt-giao { font-size:13.5px; color:var(--xam); display:flex; flex-wrap:wrap; gap:4px 14px; }
      <button data-nb="thuTien" data-sub="nopTienNB"><i class=ic data-ic=card></i> Khách báo nộp tiền <span class="huy-hieu" id="demNT"></span></button>
<div class="ban-web" id="banWeb">Phiên bản website 74 · 08/11/2026</div>
  if (!NT.length) goiNB('dsNopTien').then(r => { NT = r; if (TTH) hienTTH(); }).catch(() => {});   // v74: có phiếu khách báo nộp thì thẻ hộ hiện giờ gửi, hình thức, giao cho
  const htChu = { qr: ic('qr') + ' Quét mã QR', zl: ic('message') + ' Nhắn Zalo', goi: ic('phone') + ' Gọi điện' };
  const phieuCua = ma => (NT || []).find(p => p.ma === ma && p.thang === TTH.thang);
  $('dsTT').innerHTML = ds.length ? ds.slice(0, tthSo).map(x => { const p = phieuCua(x[0]); const da = x[6] === 'da'; return `<div class="tt-ho ${x[6]}" data-ma="${esc(x[0])}">
      <div class="nt-dau"><div><b class="nt-ten">${hoTen(x[1], x[0])}</b>${p && p.ho ? ' <span class="nhan vang">Nộp hộ</span>' : ''}<div class="nho">${esc([x[3], x[2]].filter(Boolean).join(', '))} · ${so(x[4])} m³</div></div>
        <div class="nt-tien">${tien(x[5])}<span>Tháng ${esc(TTH.thang)}</span></div></div>
      ${p ? `<div class="nt-ct"><span><i class=ic data-ic=clock></i> ${esc(p.tg)}</span><span>Hình thức: ${[...new Set(String(p.cach || '').split(', ').filter(Boolean).map(c => c === 'Chuyển khoản QR' ? 'qr' : c === 'Gọi' ? 'goi' : 'zl'))].map(k => `<b class="nt-ht ${k}">${htChu[k]}</b>`).join(' ')}</span></div>
      ${p.canbo ? `<div class="tt-giao"><span><i class=ic data-ic=user></i> Giao cho: <b>${esc(p.canbo)}</b></span></div>` : ''}` : ''}
      <div class="nt-chon" role="group" aria-label="Trạng thái thu tiền">
        <button type="button" class="nt-nut tt-nut chua ${da ? '' : 'on'}" data-v="0" aria-pressed="${!da}"><i class=ic data-ic=xCircle></i> Chưa thu</button>
        <button type="button" class="nt-nut tt-nut roi ${da ? 'on' : ''}" data-v="1" aria-pressed="${da}"><i class=ic data-ic=checkCircle></i> Đã thu</button>
      </div>
      <div class="nt-nhac" role="status" aria-live="polite"></div>
      <div class="nho nt-xn ${da ? 'da' : 'cho'}">${da ? `<i class=ic data-ic=checkCircle></i> <b>Đã thu</b>${x[7] ? ' bởi <b>' + esc(x[7]).replace(' · ', '</b> lúc ') : ''}` : `<i class=ic data-ic=hourglass></i> <b>Chưa thu</b>${p ? ' – khách đã báo nộp, kiểm tra tiền về rồi bấm Đã thu' : ''}`}</div>
    </div>`; }).join('')
  // v74: bấm đổi ngay, máy chủ ghi ngầm, có Hoàn tác 8 giây (giống phiếu Khách báo nộp tiền). Lãnh đạo chỉ xem.
    const the = b.closest('.tt-ho'), ma = the.dataset.ma, x = TTH.ds.find(y => y[0] === ma), moi = b.dataset.v === '1';
    if (!x) return;
    if ((x[6] === 'da') === moi) { the.querySelector('.nt-nhac').innerHTML = moi ? 'Hộ này <b>đang là Đã thu</b>. Ghi nhầm thì bấm <b>Chưa thu</b>.' : 'Hộ này <b>đang là Chưa thu</b>. Nhận đủ tiền thì bấm <b>Đã thu</b>.'; return; }
    const cu6 = x[6], cu7 = x[7], ky = TTH.thang, ten = x[1];
    const dat = (da, nguoi) => { x[6] = da ? 'da' : 'chua'; x[7] = da ? nguoi : ''; const p = phieuCua(ma); if (p) { p.daNop = da; p.nv = da && ND ? ND.ten : ''; p.tgxn = da ? 'vừa xong' : ''; } hienTTH(); };
    dat(moi, ND ? ND.ten + ' · vừa xong' : '');
    const viec = goiNB('danhDauThuTien', ky, [ma], moi).then(() => ghiTC(moi ? 'Đánh dấu đã thu' : 'Đánh dấu chưa thu', ma)).catch(e => { x[6] = cu6; x[7] = cu7; hienTTH(); $('loiTT').textContent = e; baoLoi('Chưa ghi được: ' + e); throw e; });
    baoHoanTac('Đã ghi: ' + ten + ' – ' + (moi ? 'ĐÃ THU' : 'CHƯA THU') + ' tháng ' + ky, () => viec.then(() => goiNB('danhDauThuTien', ky, [ma], !moi)).then(() => { dat(!moi, cu7 || (ND ? ND.ten + ' · vừa xong' : '')); if (!moi) x[7] = cu7; ghiTC('Hoàn tác đánh dấu thu tiền', ma); hienTTH(); }));
